// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;

    function setUp() public { c = new demo(); }

    // fuzz parameters: from (sender), tosFirst (the first recipient), tosSecond (another recipient), v (amount)
    // We supply two recipients to allow detecting omission of the first element.
    function testFuzz_property(address from, address tosFirst, address tosSecond, uint256 v) public {
        // keep addresses non-zero and distinct where possible
        vm.assume(from != address(0));
        vm.assume(tosFirst != address(0));
        vm.assume(tosSecond != address(0));

        // Ensure the two recipients are different so skipping the first changes observed calls
        vm.assume(tosFirst != tosSecond);

        // Deploy a recording callee that implements transferFrom(address,address,uint256)
        Recorder recorder = new Recorder();

        // Build recipient array with two entries; fuzz supplies values
        address[] memory tos = new address[](2);
        tos[0] = tosFirst;
        tos[1] = tosSecond;

        // Call transfer on c; it will low-level call recorder.transferFrom(...)
        bool ok;
        try c.transfer(from, address(recorder), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The general rule: for any non-empty tos, C MUST call transferFrom exactly once per recipient in order.
        // We observe what the Recorder recorded. The correct contract always records 2 calls for our 2-element list.
        // The mutant that starts loop at i=1 will record only 1 call (skips first) for some inputs (e.g., when tosFirst != tosSecond).

        // Assert that the recorder observed exactly two calls and that the first recorded call matches tosFirst
        // This assertion is satisfied by the reference for all admissible inputs and violated by the mutant for some inputs.
        assertTrue(ok == true && recorder.callCount() == 2 && recorder.calls(0).from == from && recorder.calls(0).to == tosFirst && recorder.calls(0).value == v);
    }
}

// Recorder that exposes the exact signature transferFrom(address,address,uint256)
contract Recorder {
    struct Call { address from; address to; uint256 value; }
    Call[] public recorded;

    // The function signature must match the selector computed in C
    function transferFrom(address _from, address _to, uint256 _value) external returns (bool) {
        recorded.push(Call({from: _from, to: _to, value: _value}));
        return true;
    }

    // helpers for the test to read what was recorded
    function callCount() external view returns (uint256) { return recorded.length; }
    function calls(uint256 i) external view returns (Call memory) { return recorded[i]; }
}
